def mult(s, base=2):
    return (base+s)/base if s>=0 else base/(base-s)

def speed(p):
    return int(p['stats']['spe']*mult(p.get('stat_stages',{}).get('speed',0)))*(0.25 if p.get('status')=='paralysis' else 1)

def profile(a,b,m):
    t,c,p,acc,pri,crit=MOVES.get(m,('normal','physical',0,100,0,0))
    eff=1
    for bt in b['types']: eff*=CHART.get((t,bt),1)
    if not eff or c=='status': return (0,0,pri)
    sa=a.get('stat_stages',{}); sb=b.get('stat_stages',{})
    hit=min(1,acc*mult(sa.get('accuracy',0)-sb.get('evasion',0),3)/100)
    if a.get('status')=='paralysis': hit*=.75
    if m in ('fissure','guillotine','horn-drill','sheer-cold'): return (.3*b['current_hp'],.3,pri)
    fixed={'sonic-boom':20,'dragon-rage':40,'seismic-toss':50,'night-shade':50}.get(m)
    if fixed: return (hit*min(fixed,b['current_hp']),hit*(fixed>=b['current_hp']),pri)
    if not p: return (0,0,pri)
    ak,dk,ask,dsk=('atk','def','attack','defense') if c=='physical' else ('spa','spd','sp_atk','sp_def')
    avg=ko=0
    cp=(.0625,.125,.25,1/3,.5)[min(4,max(0,crit))]
    for critical,weight in ((False,1-cp),(True,cp)):
        x=sa.get(ask,0); y=sb.get(dsk,0)
        if critical: x=max(0,x); y=min(0,y)
        base=22*p*int(a['stats'][ak]*mult(x))//max(1,int(b['stats'][dk]*mult(y)))//50
        if c=='physical' and a.get('status')=='burn': base//=2
        base=(base+2)*(2 if critical else 1)
        for roll in range(85,101):
            d=base*roll//100
            if t in a['types']: d=d*3//2
            d=int(d*eff)
            avg+=weight*min(d,b['current_hp'])/16
            ko+=weight*(d>=b['current_hp'])/16
    return avg*hit,ko*hit,pri

def threat(o,a):
    names=o.get('known_moves',[])
    # Unknown attacks are approximated by ordinary STAB attacks, not hidden moves.
    guesses={'normal':'strength','fire':'flamethrower','water':'surf','grass':'energy-ball','electric':'thunderbolt','ice':'ice-beam','fighting':'brick-break','poison':'sludge-bomb','ground':'earthquake','flying':'aerial-ace','psychic':'psychic','bug':'x-scissor','rock':'rock-slide','ghost':'shadow-ball','dragon':'dragon-claw','dark':'dark-pulse','steel':'flash-cannon'}
    names=list(names)+[guesses[t] for t in o['types'] if t in guesses]
    return max([profile(o,a,m) for m in names]+[(0,0,0)],key=lambda x:x[0]+x[1]*a['current_hp']*.5)

def matchup(a,o):
    inc,dead,op=threat(o,a)
    best=(-1e9,0)
    for i,m in enumerate(a.get('moves',[])):
        if m.get('pp',0)<=0: continue
        dmg,ko,pr=profile(a,o,m['identifier'])
        first=1 if pr>op or (pr==op and speed(a)>speed(o)) else .5 if pr==op and speed(a)==speed(o) else 0
        survive=1-dead*(1-first)
        score=survive*(dmg/o['stats']['hp']+0.85*ko)-.65*(1-first*ko)*inc/a['max_hp']-.35*(1-first*ko)*dead
        if score>best[0]: best=(score,i)
    return best

def choose_move(state):
    legal=state.get('legal_actions',[])
    if not legal: return {'action':'struggle'}
    o=dict(state['opponent_active']); o['stats']=STATS.get(o['species'],dict(hp=150,atk=100,def_=100,spa=100,spd=100,spe=100))
    if 'def' not in o['stats']: o['stats']['def']=100
    o['current_hp']=max(1,round(o['stats']['hp']*o['hp_percent']/100))
    a=state['active_pokemon']; attacks=[x for x in legal if x['action']=='move']; switches=[x for x in legal if x['action']=='switch']
    bench={x['index']:x for x in state['bench']}
    if not attacks:
        if any(x['action']=='struggle' for x in legal): return {'action':'struggle'}
        if switches: return max(switches,key=lambda x:matchup(bench[x['index']],o)[0]+.15*bench[x['index']]['hp_percent']/100)
        return legal[0]
    score,i=matchup(a,o)
    return next((x for x in attacks if x['index']==i),attacks[0])
